    correct: 1,
    explanation: "## The First Tube\n\nBefore microscopes, anything smaller than a millimetre was invisible forever. Someone had to build a device that could see past the naked eye.\n\nIn the late 16th century, Dutch spectacle-makers **Hans and Zacharias Janssen** placed two lenses inside a tube — one at each end — and looked through. That arrangement, taught as the first **compound microscope**, is the ancestor of every instrument on a modern lab bench.\n\nHistorians still argue about absolute priority. The Janssens never published a formal paper, and other Dutch lens-grinders were experimenting at the same time. What matters for the exam is who gets the credit: Janssen, not Hooke or Leeuwenhoek, who came later as observers.\n\nWhenever a question asks who built the first compound microscope, remember: the Janssens — the lens-makers, not the naturalists.",
