    explanation: "## The Word Was Born in Cork\n\nPicture a slice of wine-bottle cork so thin you can see through it. Now imagine putting it under a microscope and seeing something no one had ever named.\n\n**Robert Hooke** did exactly that in 1665. The cork was dead tissue — only the walls remained — and under his microscope the walls looked like rows of tiny empty rooms. He called them *cellulae*, Latin for \"small rooms.\" The word **cell** entered biology.\n\nHooke was not looking for cells. He was cataloguing whatever he could find for his book *Micrographia*. The name stuck because it fit what he saw.\n\nWhenever a question asks who first described cells, remember: Hooke and cork. Not Leeuwenhoek, who came later and saw living microbes.",
