    explanation: "## Little Animals in Pond Water\n\nDried cork walls are one thing. A drop of pond water alive with swimming specks is another.\n\nIn **1674**, **Antonie van Leeuwenhoek** looked at pond water through his own hand-made microscopes and saw things moving. He called them *animalcules*. What he was actually seeing were bacteria and protozoa — single-celled life at roughly the limit of what a single-lens microscope can reach.\n\nHis instruments were deceptively simple. One tiny glass bead as a lens, held between two brass plates. But the glass was ground so finely that it reached about **300×** — enough to make bacteria visible for the first time in history.\n\nWhenever the question is living microorganisms in water, remember: Leeuwenhoek — not Hooke, who described only dead tissue.",
