    explanation: "## All Plants Are Cells\n\nObserving a few tissues is not a general law. Someone had to make the leap from *this plant is made of cells* to *every plant is made of cells*.\n\nIn **1838**, the German botanist **Matthias Schleiden** made that leap. After studying plants across many groups, he concluded that **all plants are made of cells**. That statement became the first formal pillar of **cell theory**.\n\nSchwann extended the same idea to animals the following year. Together, the two claims redefined what a living organism is: not a mass of mysterious jelly, but a community of discrete cellular units.\n\nWhenever the year is 1838 and the subject is plants, remember: Schleiden. Not Schwann (1839, animals), and not Virchow (1855, origin of cells).",
