    correct: 2,
    explanation: "## Two Names, Two Kingdoms\n\nOne scientist alone could not have founded the theory, because a single observer would only have looked at one kind of organism.\n\n**Schleiden** worked on plants. **Schwann** worked on animals. In 1838 and 1839, they made the same claim about two different kingdoms, and together the two claims became **cell theory**. Virchow added the third principle in 1855, but he did not co-found the theory — he extended it.\n\nHooke and Leeuwenhoek observed cells, but they did not generalise. Watson and Crick came over a century later, working on DNA rather than on cells.\n\nWhenever the question is \"who co-founded cell theory,\" remember: **Schleiden and Schwann**. Plant and animal, one pair.",
