    correct: 0,
    explanation: "## Two Lenses, One Product\n\nA compound microscope is called *compound* for a reason: it uses two lenses in sequence. The total magnification is their **product**, not their sum.\n\nSet the eyepiece at 10× and the objective at 40×. The image reaching your eye is magnified 10 times by the eyepiece and 40 times by the objective, so the total is **10 × 40 = 400×**. Every detail of the specimen appears 400 times larger than it actually is.\n\nIf you added instead of multiplied, you would get 50× — a number too small to describe what the microscope is actually doing. Real microscopes routinely reach 1000× or more with just two lenses, and simple addition could never explain that.\n\nWhenever a question asks for total magnification, remember: **multiply** the eyepiece by the objective. Never add.",
