    correct: 2,
    explanation: "## The Big Focus Knob\n\nYou cannot focus on something that is completely out of range. At the start of every session, the specimen looks like a grey blur, and no amount of tiny twisting will find it.\n\nThe **coarse adjustment knob** is the one you use first. It moves the stage — or the body tube, on some microscopes — in **large, fast steps**, sweeping through a wide range of distances until the specimen comes roughly into view.\n\nThis is why the coarse knob is only used with the low-power objectives (4× and 10×). At 40×, a large turn can drive the objective straight into the slide and crack the coverslip — or worse, scratch the lens. Once the specimen is roughly in focus, you switch to the **fine adjustment knob** for the last, precise turns.\n\nWhenever a question asks which knob brings a specimen into rough view, remember: the coarse knob — big movements, low power only.",
