    explanation: "## The Precision Knob\n\nOnce the specimen is roughly in view, the smallest turn of the stage can make the difference between a fuzzy blur and a crisp, sharp image. That is the fine knob's job.\n\nThe **fine adjustment knob** moves the stage in **very small steps**. At high magnification — 40× or 100× — a tiny shift in distance makes a huge difference in sharpness, so precision matters more than range.\n\nBecause the objective lenses on most microscopes are **parfocal**, switching between them leaves the specimen nearly in focus. A small twist of the fine knob finishes the job. This is why you focus with the coarse knob only once, then use the fine knob for every subsequent objective change.\n\nWhenever a question asks which knob sharpens an already-roughly-visible specimen, remember: the fine knob — small turns, high power.",
