    correct: 3,
    explanation: "## The Lens Carousel\n\nA microscope with one lens would be a one-trick instrument. A microscope with several lenses needs a way to switch between them without unscrewing anything.\n\nThe **revolving nosepiece** is a rotating metal disc that **holds the objective lenses**. Turn it and it clicks a different objective into the light path, changing the magnification instantly.\n\nBecause most objectives are **parfocal**, you can swap them without losing focus. A specimen focused at 10× stays roughly in view at 40×, requiring only a small tweak with the fine knob. Without this, every lens change would mean re-finding the specimen from scratch.\n\nWhenever a question asks how you switch magnifications on a microscope, remember: the revolving nosepiece — the turret that carries the objectives.",
