    correct: 2,
    explanation: "## The Structural Spine\n\nEvery microscope needs a frame strong enough to hold the optics perfectly aligned. If any component shifts by even a fraction of a millimetre, the image blurs.\n\nThe **arm** is that frame. It is the curved metal piece that connects the base at the bottom to the body tube, stage, and focus knobs at the top. Every optical and mechanical part is bolted to it, holding them in the exact positions they need to be in.\n\nThe arm also serves a second purpose: it is the natural grip when you carry the microscope. The rule is one hand on the arm, one hand under the base. Lifting a microscope by any other part risks knocking it out of alignment — a repair that costs more than the instrument.\n\nWhenever a question asks what supports the body tube and stage, remember: the arm — the microscope's structural spine.",
