    correct: 2,
    explanation: "## The Foundation\n\nA microscope on a shaky bench is worse than useless. Every adjustment sends a vibration through the optics, and the image jitters instead of sharpening.\n\nThe **base** is the flat, sturdy bottom of the microscope. It supports the entire instrument, keeps it stable on the bench, and — together with the arm — is one of the two points where you grip the microscope when carrying it.\n\nA wide, heavy base also prevents the microscope from tipping when the stage is pushed to one extreme or the other. When you focus on something at the edge of a slide, the base is what stops the whole instrument from pitching forward.\n\nWhenever a question asks what keeps a microscope stable, remember: the base — the flat bottom that supports everything above.",
