    correct: 1,
    explanation: "## Multiply the Lenses\n\nEvery compound microscope has two lenses in a line. The first magnifies the specimen, and the second magnifies the already-magnified image. The two effects stack — but not by adding.\n\nThe formula is:\n\n$$M_{\\text{final}} = M_{\\text{ocular}} \\times M_{\\text{objective}}$$\n\nPut a **10×** eyepiece over a **40×** objective and the total is **400×**. Put the same eyepiece over a **100×** oil objective and it becomes **1000×**. The eyepiece does not add 10× to the total; it multiplies it.\n\nThe condenser and diaphragm are not part of this product. They affect illumination and contrast, not magnification. Only the two lenses in the light path count.\n\nWhenever a question asks for total magnification, remember: **multiply** — eyepiece × objective. Adding is the classic mistake.",
    status: "approved"
