    explanation: "## The Textbook View\n\nClose your eyes and picture the microscope you first used in a school lab. You put a stained slide on the stage, looked through the eyepiece, and saw dark shapes against a bright circle of light.\n\nThat mental image is **brightfield microscopy**. It shines light from below up through the specimen. Where the specimen absorbs or refracts light, that spot looks darker. The background — where light passes straight through — looks bright. That is where the name comes from: bright background, dark specimen.\n\nNearly every student microscope on Earth is a brightfield instrument, and most clinical samples — blood smears, gram stains, urine sediments — are examined with one.\n\nWhenever a question asks which microscope shows dark objects on a light background, remember: brightfield — the standard light microscope.",
