    correct: 3,
    explanation: "## Seeing the Spiral\n\n*Treponema pallidum* — the bacterium that causes syphilis — is a long, thin spirochete about 0.15 µm thick. It is so slender that a brightfield microscope cannot see it at all. It matches the refractive index of the surrounding fluid and casts no shadow.\n\nThe **darkfield microscope** is what reveals it. With the direct light blocked, only light scattered off the bacterium's surface reaches the lens. The spirochete appears as a glowing spiral against a black background, and — because it is alive — you can watch it move.\n\nThis is the only way to diagnose syphilis by direct observation. Darkfield is also used for other thin spirochetes such as *Borrelia burgdorferi*, the cause of Lyme disease.\n\nWhenever a question asks how living spirochetes are seen, remember: darkfield — the bright spiral on a black field.",
