    correct: 2,
    explanation: "## Light that Glows Back\n\nImagine shining blue light at a slide and seeing green light bounce back from it. That is the trick fluorescence microscopy pulls off.\n\nA **fluorescence microscope** uses **fluorochromes** — dyes that absorb light at one wavelength and emit it at a longer one. Shine blue light on a fluorochrome-labelled sample and the dye glows green; shine ultraviolet and it may glow red or orange.\n\nThe sample itself becomes the light source, which is why even tiny quantities of target are visible against a black background. Immunofluorescence uses this principle to detect specific pathogens: an antibody tagged with a fluorochrome binds to the microbe, and the microscope picks out the glow.\n\nWhenever a question asks which microscope uses glowing dyes, remember: fluorescence — dyes that absorb short wavelengths and emit longer ones.",
