    correct: 3,
    explanation: "## Blocking the Centre\n\nEvery microscope that makes the specimen glow uses the same principle: hide the light, show the subject.\n\nThe **darkfield microscope** places a small **opaque stop** — a black disc — inside the condenser, right in the path of the illuminator's direct beam. Light travelling straight up the middle of the microscope is blocked. Only light that has already been **refracted or scattered by the specimen** makes it into the objective.\n\nThe result is a bright specimen on a completely dark background. The technique is especially powerful for viewing transparent, live, unstained specimens that would be nearly invisible under brightfield.\n\nWhenever a question asks what creates the dark background of a darkfield image, remember: the opaque stop — the black disc that blocks the centre of the beam.",
    status: "approved"
