    correct: 1,
    explanation: "## Glowing Antibodies\n\nAntibodies are nature's targeting systems. Attach a fluorescent tag to one, and you have a glowing probe that finds exactly one thing — the microbe you are looking for.\n\n**Immunofluorescence** works this way. A fluorochrome-tagged antibody is added to a sample, binds to its target pathogen, and shows up under a **fluorescence microscope** as a bright spot in the field. Only the labelled pathogen glows; everything else stays dark.\n\nThis technique is used in clinics to detect pathogens such as *Treponema pallidum* and *Mycobacterium tuberculosis*. It is fast, specific, and sensitive — capable of showing that a pathogen is present even when cultures fail.\n\nWhenever a question mentions immunofluorescence or fluorochrome-tagged antibodies, remember: the microscope of choice is the fluorescence microscope.",
