    correct: 3,
    explanation: "## The Electron Source\n\nBefore an electron microscope can magnify anything, it needs electrons. That job belongs to the top of the column.\n\nThe **electron gun** sits at the very top of the TEM. A heated filament — the cathode — releases electrons, and a high positive voltage at the anode accelerates them into a focused beam. That beam then travels down the column, through the specimen, and onto the detector at the bottom.\n\nEverything else in the microscope — the magnetic lenses, the specimen holder, the vacuum pumps — exists to control and use the beam the gun produced. Without the gun, nothing moves.\n\nWhenever a question asks where the electrons in a TEM come from, remember: the electron gun — the heated filament at the top of the column.",
