    correct: 0,
    explanation: "## Through, Not Across\n\nThe difference between the two electron microscopes is a single word: *through*.\n\nA **transmission electron microscope (TEM)** fires a beam of electrons **through** an extremely thin specimen. Where the specimen is denser, fewer electrons pass through; where it is thinner, more electrons make it. The pattern of electrons that reach the detector becomes the image.\n\nThis is why TEM shows internal structure — organelles, membranes, ribosomes — at resolutions far beyond anything a light microscope can reach. The catch is that the specimen must be cut into sections 20–100 nm thick and dried, so nothing living can be viewed.\n\nWhenever a question asks what a TEM does, remember: it transmits electrons **through** the specimen to reveal internal structure.",
