    correct: 2,
    explanation: "## Thin Enough to Transmit\n\nElectrons are not very good at penetrating matter. Fire them at a chunk of tissue and they simply stop. The specimen has to be made thin enough that electrons can tunnel through it.\n\nFor the **TEM**, that means cutting the specimen into sections **20 to 100 nm thick** — about a hundredth of the diameter of a red blood cell. Cells are too soft to cut that thinly, so they are first embedded in hard plastic resin, dehydrated through an ethanol series, and sliced with a diamond-bladed instrument called an **ultramicrotome**.\n\nThe resulting sections are mounted on copper grids and stained with heavy metal salts to make the internal structures visible. Only then can the beam pass through.\n\nWhenever a question asks what TEM specimens require, remember: **ultra-thin sections** — thin enough for electrons to pass through.",
