    explanation: "## Touching Without Touching\n\nImagine running your finger over a surface so gently that you never actually make contact — yet you can feel every atom. That is what a scanning tunneling microscope does.\n\nThe **scanning tunneling microscope (STM)** uses an ultrafine tungsten tip held just above the specimen — a fraction of a nanometre away. A small voltage is applied, and electrons **quantum-tunnel** across the gap between tip and surface, producing a tiny current.\n\nThe strength of that current depends on the width of the gap. As the tip scans across the surface, the current rises over ridges and falls over valleys. The result is a map of individual **atoms** — the finest detail any microscope can produce.\n\nWhenever a question mentions a tungsten tip and a tunneling current, remember: the scanning tunneling microscope.",
