    correct: 0,
    explanation: "## Anchoring and Preserving\n\nYou cannot look at a bacterium that has washed off the slide.\n\n**Fixation** is the first real step in specimen preparation. It does two jobs at once: it **attaches the cells firmly to the glass slide**, and it **preserves their cellular structure** so that later steps do not destroy them.\n\nThe two standard methods are **heat fixation** — passing the slide briefly over a flame — and **chemical fixation** with reagents such as formalin or ethanol. Both kill the microorganisms, stopping their movement and metabolism, and lock their proteins and membranes in place.\n\nWithout fixation, the stain would wash the specimen off the slide, and the image would fade before you could look at it.\n\nWhenever a question asks what happens before staining, remember: fixation — the step that glues and preserves the cells.",
