    correct: 0,
    explanation: "## One Colour or Two\n\nImagine two kinds of bacteria sitting side by side on a slide. To a simple stain, they look identical — both dyed the same shade.\n\nA **simple stain** uses a single dye, so all cells in the sample end up the same colour. Useful for counting and seeing shapes, but it tells you nothing about what kind of bacteria you are looking at.\n\nA **differential stain** uses **multiple dyes** and exploits differences in cell structure to colour different organisms **differently**. Gram staining, for example, sorts bacteria into purple and pink classes based on the thickness of their peptidoglycan layer. Acid-fast, endospore, and capsule stains work the same way — different dyes, different cell chemistry, different outcomes.\n\nWhenever a question asks what a differential stain does that a simple stain cannot, remember: it produces **different colours for different organisms**.",
