    optionRationales: ["Map units measure recombination frequency, not chromosome count.",null,"Population fixation is an evolutionary concept, not a map unit.","Amino acid changes are molecular effects, not genetic map units."],
    correct: 1,
    explanation: "## Measuring Distance on a Chromosome\n\nHow do you draw a map of something you cannot see? You use a measurable signal — and for chromosomes, the signal is recombination.\n\nA **map unit** (also called a **centimorgan**, abbreviated cM) equals a **1% recombination frequency** between two genes. If two genes recombine in 1% of offspring, they are 1 map unit apart. If 10%, they are 10 map units apart.\n\nThis gives geneticists a way to estimate the physical distance between genes without ever looking at the DNA directly. The map is built entirely from breeding data — counts of how often traits appear together or separately in offspring.\n\nThe system breaks down for genes very far apart on the same chromosome, because multiple crossovers can cancel each other out and make them look closer than they are.\n\nWhenever a question asks what a map unit represents, remember: **1% recombination** — the recombination-based unit of genetic distance.",
